'use strict';
/* The Accuracy view.
 *
 * Every number here comes from window.ACCURACY_DATA, which is GENERATED by
 * eval/build_accuracy_data.py from stored measurements (answers CSV, retrieval
 * snapshot, floor calibration, src/config.py, the live Ollama model list).
 * No measured number on this page is typed in by hand (the two targets, 85% and
 * 90%, are the brief's). If a source is missing, the field
 * says "not measured" rather than showing a guess.
 *
 * Regenerate:  python -m eval.build_accuracy_data
 */
(function () {
  const root = document.getElementById('acc');
  if (!root) return;
  const D = window.ACCURACY_DATA;
  if (!D) {
    root.innerHTML = '<h2>Accuracy</h2><div class="callout warn"><p>No accuracy data file found. ' +
      'Run <code>python -m eval.build_accuracy_data</code> and reload this page.</p></div>';
    return;
  }

  const esc = (s) => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const NM = '<span class="fnote">not measured</span>';
  const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);
  const fmtDate = (iso) => {
    if (!iso) return 'unknown date';
    const d = new Date(iso);
    return isNaN(d) ? iso : d.toLocaleString([], { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  };
  const rows = (list) => list.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('');
  const table = (heads, list) =>
    `<table><thead><tr>${heads.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows(list)}</tbody></table>`;
  const stat = (big, label, small) =>
    `<div class="stat"><b>${big}</b><span>${label}</span>${small ? `<small>${small}</small>` : ''}</div>`;
  const bar = (a, b) =>
    `<div class="bar ${a === b ? '' : 'part'}"><i style="width:${pct(a, b)}%"></i></div>`;
  const pill = (v) => v === 'CORRECT' ? '<span class="pill ok">Correct</span>'
    : v === 'ERROR' ? '<span class="pill bad">Error</span>' : '<span class="pill bad">Incorrect</span>';
  const label = (t) => String(t).replace(/_/g, ' ');

  const A = D.answers, C = D.code, R = D.retrieval, F = D.floor;
  const c = A.counts;
  const out = [];

  /* ---------------------------------------------------------- headline */
  out.push(`
    <h2>Accuracy</h2>
    <p class="lead">What was measured, on which code, with which models. Plain numbers only —
    nothing on this page is estimated.</p>

    <div class="stats">
      ${stat(`${c.CORRECT} / ${A.n}`, 'answers judged correct', `${pct(c.CORRECT, A.n)}% — target 85%`)}
      ${R ? stat(`${R.hits} / ${R.n}`, 'right document in top 5', `${pct(R.hits, R.n)}% — target 90%`) : stat('—', 'right document in top 5', 'not measured yet')}
      ${stat(c.ERROR, 'technical errors', 'any error invalidates a run')}
      ${stat(A.latency.mean == null ? '—' : A.latency.mean + ' s', 'average time per answer', 'CPU only, one question at a time')}
    </div>
    <p class="srcnote">Source: <code>eval/results/${esc(A.file)}</code>, run started ${esc(fmtDate(A.run_started))}.
    The 40 questions come from the project brief and were never edited.</p>
  `);

  /* -------------------------------------------- is this result current? */
  const changed = C.changed_since || [], dirty = C.uncommitted || [];
  if (C.evaluated_commit && !changed.length && !dirty.length) {
    out.push(`<div class="callout"><p><b>This result matches the code now running.</b>
      Evaluated on commit <code>${esc(C.evaluated_commit)}</code>; no answer-affecting file has changed since.</p></div>`);
  } else {
    const list = changed.concat(dirty.filter(f => !changed.includes(f)));
    out.push(`<div class="callout warn"><p><b>Read this first: the code has changed since this result was measured.</b></p>
      <p>The ${c.CORRECT}/${A.n} above was measured on commit <code>${esc(C.evaluated_commit || 'unknown')}</code>.
      The code now is <code>${esc(C.head_commit || 'unknown')}</code>${dirty.length ? ' plus uncommitted edits' : ''}.
      These answer-affecting files differ: ${list.map(f => `<code>${esc(f)}</code>`).join(', ') || 'none found'}.</p>
      <p>Until the full 40-question test is run again on the current code, the number above describes the
      <em>earlier</em> code, not the current one.</p></div>`);
  }

  /* ------------------------------------------------------ 1 by type */
  out.push(`<h3><span class="num">1</span>Answer accuracy by kind of question</h3>`);
  out.push(table(['Kind of question', 'Correct', 'Out of', 'Score', ''],
    Object.entries(A.by_type).map(([t, v]) => [
      `<b>${esc(label(t))}</b>`, v.correct, v.n, pct(v.correct, v.n) + '%', bar(v.correct, v.n)])));
  out.push(`<p class="srcnote">Averages hide failures, so the score is broken out by type.</p>`);

  /* ------------------------------------------------------ 2 traps */
  out.push(`<h3><span class="num">2</span>The six traps hidden in the documents</h3>`);
  out.push(table(['Trap', 'Questions', 'Correct'],
    A.traps.map(t => [esc(t.name), esc(t.ids.join(', ')),
      `<span class="pill ${t.correct === t.n ? 'ok' : 'bad'}">${t.correct} / ${t.n}</span>`])));

  /* ------------------------------------------------------ 3 wrong */
  const wrong = A.rows.filter(r => r.verdict !== 'CORRECT');
  out.push(`<h3><span class="num">3</span>${wrong.length ? 'Questions answered wrongly' : 'Questions answered wrongly: none'}</h3>`);
  if (wrong.length) {
    out.push(wrong.map(r => `
      <div class="callout warn">
        <p><b>${esc(r.id)} · ${esc(label(r.type))}</b> — ${esc(r.question)}</p>
        <p><b>Expected:</b> ${esc(r.expected)}</p>
        <p><b>The assistant said:</b> ${esc(r.actual)}</p>
        <p><b>The judge’s reason:</b> ${esc(r.reason)}</p>
      </div>`).join(''));
  }

  /* ------------------------------------------------------ 4 retrieval */
  out.push(`<h3><span class="num">4</span>Finding the right document (before any model writes anything)</h3>`);
  if (R) {
    out.push(`<div class="stats three">
      ${stat(`${R.hits} / ${R.n}`, 'found in top 5', pct(R.hits, R.n) + '%')}
      ${stat(`${R.rank1} / ${R.n}`, 'found at rank 1', 'the number that separates good from lucky')}
      ${stat(R.mean_rank, 'mean rank of the right document', '1.00 is perfect')}
    </div>`);
    out.push(table(['Kind of question', 'Found', 'Out of'],
      Object.entries(R.by_type).map(([t, v]) => [esc(label(t)), v.hit, v.n])));
    if (R.not_rank1.length) {
      out.push(`<p class="srcnote">Not at rank 1: ${R.not_rank1.map(x => `${esc(x.id)} (rank ${x.rank})`).join(', ')}.</p>`);
    }
    if (R.misses.length) {
      out.push(`<div class="callout warn"><p><b>Missed:</b> ${R.misses.map(m => esc(m.id)).join(', ')}</p></div>`);
    }
    out.push(`<p class="srcnote">Source: <code>eval/results/${esc(R.file)}</code>, measured ${esc(fmtDate(R.measured_at))}.
    With only 12 documents, “top 5” is a loose test, so rank 1 is shown too.
    The 4 refusal questions have no source document and belong to the answer test.</p>`);
  } else {
    out.push(`<p>${NM} — run <code>python -m eval.build_accuracy_data --retrieval</code>.</p>`);
  }
  if (F) {
    out.push(`<p>The <b>relevance floor</b> is how the assistant knows to say “not in the documents”.
      The lowest score of any real question was <b>${F.lowest_in_scope}</b>; the floor is set at <b>${F.configured}</b>, just below it.
      Scores of the questions that should be refused:</p>`);
    out.push(table(['Question', 'Best score', 'Closest document'],
      F.out_of_scope.map(o => [esc(o.id), o.score, esc(o.doc)])));
    const hi = F.out_of_scope.filter(o => o.score >= F.configured);
    if (hi.length) {
      out.push(`<p class="srcnote">${hi.map(o => esc(o.id)).join(', ')} score${hi.length === 1 ? 's' : ''} above the floor
      (${hi.map(o => o.score).join(', ')}), so the floor alone does not refuse ${hi.length === 1 ? 'it' : 'them'};
      the prompt rules do.</p>`);
    }
  }

  /* ------------------------------------------------------ 5 history */
  out.push(`<h3><span class="num">5</span>Every full test run so far</h3>`);
  out.push(table(['Run', 'Correct', 'Errors', 'What changed from the run before'],
    D.history.map(h => [esc(fmtDate(h.when)), `${h.correct} / ${h.n}`, h.errors,
      h.changed.length ? h.changed.map(x => `${esc(x.id)}: ${esc(x.from.toLowerCase())} → ${esc(x.to.toLowerCase())}`).join('<br>')
        : (h.when === D.history[0].when ? 'first run' : 'no change')])));

  /* ------------------------------------------------------ 6 models */
  out.push(`<h3><span class="num">6</span>Models in use</h3>`);
  out.push(table(['Job', 'Model', 'Size', 'Precision', 'Runs on'],
    D.models.map(m => [esc(m.role),
      `<b><code>${esc(m.name)}</code></b>${m.params ? `<br><small>${esc(m.params)} parameters</small>` : ''}`,
      m.size_gb == null ? '—' : m.size_gb + ' GB',
      m.quant ? esc(m.quant) : '—',
      esc(m.runtime)])));
  out.push(`<p class="srcnote">Read from the running Ollama server. <b>Q4_K_M</b> means the model’s weights are stored in about 4 bits
    (already quantised by its publisher; the project did not re-quantise anything). <b>F16</b> means unquantised.
    The re-ranker is not an Ollama model and its licence is non-commercial (CC-BY-NC); an MIT-licensed fallback is configured.</p>`);

  /* ------------------------------------------------------ 7 settings */
  out.push(`<h3><span class="num">7</span>Current settings</h3>`);
  out.push(table(['Setting', 'Value', 'Meaning'],
    D.settings.map(s => [esc(s.name), `<code>${esc(s.value)}</code>`, esc(s.note)])));
  if (D.corpus && D.corpus.documents != null) {
    out.push(`<p class="srcnote">Document set: ${D.corpus.documents} documents cut into ${D.corpus.passages} passages.</p>`);
  }

  /* ------------------------------------------------------ 8 speed */
  const L = A.latency;
  out.push(`<h3><span class="num">8</span>Speed in this test run</h3>`);
  out.push(`<div class="stats">
    ${stat(L.mean + ' s', 'average')}${stat(L.median + ' s', 'median')}
    ${stat(L.max + ' s', 'slowest')}${stat(L.total_minutes + ' min', `all ${A.n} questions`)}
  </div>`);
  out.push(`<p class="srcnote">Time per question includes search, re-ranking, writing the answer and judging it, on a CPU-only machine.
    Speed depends on the machine; accuracy did not change when the same code was run on a second, faster machine
    (recorded in the project handoff notes).</p>`);

  /* ------------------------------------------------------ 9 all rows */
  out.push(`<h3><span class="num">9</span>Every question, expected answer and actual answer</h3>`);
  out.push(`<p class="srcnote">Click a row to open it.</p>`);
  out.push(A.rows.map(r => `
    <details class="q"><summary><span class="qid">${esc(r.id)}</span>
      <span class="qt">${esc(r.question)}</span>${pill(r.verdict)}</summary>
      <div class="qbody">
        <p><b>Type:</b> ${esc(label(r.type))}${r.seconds != null ? ` · <b>Time:</b> ${r.seconds} s` : ''}</p>
        <p><b>Expected:</b> ${esc(r.expected)}</p>
        <p><b>Assistant:</b> ${esc(r.actual)}</p>
        <p><b>Judge:</b> ${esc(r.reason)}</p>
        ${r.citations.length ? `<p><b>Documents shown as sources:</b> ${r.citations.map(x => `<code>${esc(x)}</code>`).join(' ')}</p>` : ''}
      </div></details>`).join(''));

  /* ------------------------------------------------------ 10 limits */
  out.push(`<h3><span class="num">10</span>How reliable is this measurement</h3>
    <ul class="plain">
      <li><b>Small test.</b> 40 questions. One question is 2.5 points, so a single flip moves the score by that much.</li>
      <li><b>The judge is a small model.</b> The same ${esc(D.models[0].name)} model that writes answers also grades them.
        It has been wrong in both directions: it marked two correct answers wrong (Q15, Q19, first run) and, on a second machine,
        marked a wrong answer correct (Q33). So exact numbers and codes are checked by fixed rules first, and every verdict
        with its reason is stored and listed above for a human to audit.</li>
      <li><b>One run each.</b> The model has a little randomness (temperature ${esc(D.settings.find(s => s.name.startsWith('Answer-writing')).value)}).
        A re-run can differ by a question.</li>
      <li><b>Not a guarantee for new questions.</b> This measures these 40 questions on these 12 documents.</li>
      <li><b>One person at a time.</b> The server answers one question at a time by design.</li>
    </ul>`);

  root.innerHTML = out.join('\n');
})();
